explicit_branches.valve/limits.py:
MAX_PERCENT = 100
MIN_PERCENT = 0


def opening_percent(raw: int) -> int:
    if raw > MAX_PERCENT:
        return MAX_PERCENT
    if raw < MIN_PERCENT:
        return MIN_PERCENT
    return raw

min_max.valve/limits.py:
MAX_PERCENT = 100
MIN_PERCENT = 0


def opening_percent(raw: int) -> int:
    return max(MIN_PERCENT, min(MAX_PERCENT, raw))

